  return page.evaluate(() => {
    const list = (window as unknown as { __testAudio: HTMLAudioElement[] }).__testAudio;
    const music = list.filter((audio) => audio.loop).at(-1);
    return !!music && !music.paused && music.currentTime > 0 && !music.error;
  });
}
